def withdraw_cas(self, amount: int) -> tuple[bool, int]:
        if amount <= 0:
            raise ValueError('Amount must be positive')
        with self._lock:
            if self._balance < amount:
                return False, self._balance
            self._balance -= amount
            self._version += 1
            return True, self._balance
